const aggregated = $input.first().json;
const raceContext = aggregated.race_context || {};
const newsHeadlines = aggregated.news_headlines || [];

// Build search string from ESPN race context fields
const raceContextStr = [
  raceContext.raceName || '',
  raceContext.shortName || '',
  raceContext.venueCity || '',
  raceContext.venueCountry || '',
  raceContext.venue || ''
].join(' ').toLowerCase();

// Fallback: scan all news headlines for circuit keyword
const headlinesStr = newsHeadlines.join(' ').toLowerCase();

// Combined search string: race context first (more authoritative), headlines as fallback
const searchStr = raceContextStr + ' ' + headlinesStr;

let matchedKey = null;
let matchedCircuit = null;
for (const [key, circuit] of Object.entries(CIRCUITS)) {
  if (searchStr.includes(key)) {
    matchedKey = key;
    matchedCircuit = circuit;
    break;
  }
}

let circuitBlock = '';
if (matchedCircuit) {
  circuitBlock = [
    `🏁 CIRCUIT: ${matchedCircuit.name} — ${matchedCircuit.country}`,
    `💻 TYPE: ${matchedCircuit.type} | ${matchedCircuit.laps} laps | ${matchedCircuit.length}`,
    `📏 CHARACTERISTICS: ${matchedCircuit.characteristics}`,
    `🔄 OVERTAKING: ${matchedCircuit.overtaking}`,
    `🌧️ WEATHER RISK: ${matchedCircuit.weather_risk}`,
    `🔑 KEY FACTORS: ${matchedCircuit.key_factors}`
  ].join('\n');
} else {
  const venueName = raceContext.venue || raceContext.raceName || 'Venue TBD';
  circuitBlock = `🏁 CIRCUIT: ${venueName} — Circuit data not yet in lookup table`;
}

return [{
  json: {
    ...aggregated,
    circuit_context: circuitBlock,
    circuit_matched: matchedCircuit !== null,
    circuit_name: matchedCircuit ? matchedCircuit.name : null,
    circuit_match_key: matchedKey
  }
}];

// Driver name normalizations (API returns full legal names)
const DRIVER_NAME_MAP = {
  'Andrea Kimi Antonelli': 'Kimi Antonelli'
};
function normalizeName(full) {
  return DRIVER_NAME_MAP[full] || full;
}


// ── Driver Standings (Jolpica/Ergast) ─────────────────────────────────────
let driverStandings = [];
try {
  const dsJson = $('F1 Get Driver Standings').first().json;
  const list = dsJson?.MRData?.StandingsTable?.StandingsLists?.[0];
  driverStandings = (list?.DriverStandings || []).map(s => ({
    position: parseInt(s.position),
    name: normalizeName(s.Driver.givenName + ' ' + s.Driver.familyName),
    team: s.Constructors[0]?.name || '',
    points: parseFloat(s.points),
    wins: parseInt(s.wins)
  }));
} catch(e) { driverStandings = []; }

// ── Constructor Standings ──────────────────────────────────────────────────
let constructorStandings = [];
try {
  const csJson = $('F1 Get Constructor Standings').first().json;
  const list = csJson?.MRData?.StandingsTable?.StandingsLists?.[0];
  constructorStandings = (list?.ConstructorStandings || []).map(s => ({
    position: parseInt(s.position),
    name: s.Constructor.name,
    points: parseFloat(s.points),
    wins: parseInt(s.wins)
  }));
} catch(e) { constructorStandings = []; }

// ── Last Race Results ──────────────────────────────────────────────────────
let lastRace = {};
try {
  const lrJson = $('F1 Get Last Race Results').first().json;
  const race = lrJson?.MRData?.RaceTable?.Races?.[0];
  if (race) {
    const results = race.Results || [];
    const dnfs = results.filter(r => r.status !== 'Finished' && !r.status.startsWith('+'));
    lastRace = {
      name: race.raceName,
      date: race.date,
      winner: results[0]
        ? results[0].Driver.givenName + ' ' + results[0].Driver.familyName
          + ' (' + (results[0].Constructor?.name || '') + ')'
        : 'Unknown',
      podium: results.slice(0, 3).map(r =>
        r.Driver.givenName + ' ' + r.Driver.familyName + ' (' + (r.Constructor?.name || '') + ')'
      ),
      dnfs: dnfs.slice(0, 5).map(r =>
        r.Driver.givenName + ' ' + r.Driver.familyName + ' — ' + r.status
      )
    };
  }
} catch(e) { lastRace = { name: 'Unknown', winner: '', podium: [], dnfs: [] }; }

// ── Carry forward all data from F1 Circuit Context ─────────────────────────
const circuitData = $('F1 Circuit Context').first().json;

// ── Format blocks for Bobby Vegas prompt ──────────────────────────────────
const top10 = driverStandings.slice(0, 10);
const top5c = constructorStandings.slice(0, 5);

const championshipBlock = top10.length > 0
  ? top10.map(d =>
      `P${d.position}: ${d.name} (${d.team}) — ${d.points} pts${d.wins > 0 ? ', ' + d.wins + ' W' : ''}`
    ).join('\n')
  : 'Standings unavailable';

const constructorBlock = top5c.length > 0
  ? top5c.map(c => `P${c.position}: ${c.name} — ${c.points} pts`).join('\n')
  : 'Standings unavailable';

const lastRaceBlock = lastRace.winner
  ? [
      `Race: ${lastRace.name} (${lastRace.date})`,
      `Winner: ${lastRace.winner}`,
      `Podium: ${lastRace.podium.join(' | ')}`,
      lastRace.dnfs.length > 0
        ? `DNFs/Issues: ${lastRace.dnfs.join(', ')}`
        : 'No notable DNFs'
    ].join('\n')
  : 'Last race data unavailable';

const leader = driverStandings[0] || {};
const leaderStr = leader.name
  ? `${leader.name} (${leader.team}) — ${leader.points} pts, ${leader.wins} wins`
  : 'Unknown';

return [{
  json: {
    ...circuitData,
    championship_standings: championshipBlock,
    team_standings: constructorBlock,
    last_race_summary: lastRaceBlock,
    championship_leader: leaderStr,
    driver_standings_raw: top10,
    team_standings_raw: top5c
  }
}];

